import{_ as t,o as i,c as a,ae as s}from"./chunks/framework.CeK7r8F_.js";const u=JSON.parse('{"title":"Built-in Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"features/versioning.md","filePath":"features/versioning.md"}'),o={name:"features/versioning.md"};function r(n,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="built-in-versioning" tabindex="-1">Built-in Versioning <a class="header-anchor" href="#built-in-versioning" aria-label="Permalink to &quot;Built-in Versioning&quot;">​</a></h1><p>DOM ORM can automatically commit your XML data file to a Git or Mercurial repository after every write. This gives you a full audit trail and an off-site backup without any extra infrastructure. DOM ORM supports <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> and <a href="https://www.mercurial-scm.org/" target="_blank" rel="noreferrer">Mercurial</a> out of the box.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><strong>Git:</strong> <code>git</code> must be on the system <code>PATH</code>. Run <code>git --version</code> to verify.</li><li><strong>Mercurial:</strong> <code>hg</code> must be on the system <code>PATH</code>. Run <code>hg --version</code> to verify.</li><li>The storage directory (configured under <code>flysystem.config.location</code>) must already be inside an initialised repository (<code>git init</code> / <code>hg init</code>). DOM ORM does <strong>not</strong> create the repo for you.</li><li>For push to work, a remote must be configured and any required credentials (SSH key or credential helper) must be available to the PHP process.</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>In your <code>config/dom-orm.php</code> file, there are three settings used for this feature:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;dom-orm&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;versioning&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;version_control&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;git&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;version_control_push&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;manual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ];</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>versioning</code></td><td><code>true</code> / <code>false</code></td><td>Master switch. Defaults to <code>false</code> — no VCS activity until explicitly enabled.</td></tr><tr><td><code>version_control</code></td><td><code>git</code> / <code>hg</code></td><td>Which VCS binary to use. Defaults to <code>&#39;git&#39;</code>.</td></tr><tr><td><code>version_control_push</code></td><td><code>manual</code></td><td>Commit locally on every write, but <strong>never push</strong> automatically. Use a cron job or CI to push on your own schedule.</td></tr><tr><td></td><td><code>on_persist</code></td><td>Commit <strong>and</strong> push on every write. Convenient for low-traffic projects where blocking on a network call is acceptable.</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> Start with <code>version_control_push: &#39;manual&#39;</code> and add a cron-driven push once you have verified that commits are being created correctly.</p></blockquote><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>After DOM ORM writes the XML file, <code>VcsService::commit()</code> is called automatically.</li><li>It stages all changes in the storage directory (<code>add -A</code> / <code>addremove</code>).</li><li>It creates a commit whose message names the calling class and method</li><li>If <code>version_control_push</code> is <code>on_persist</code>, it pushes to the configured remote.</li></ol><p>Failures are <strong>non-fatal</strong> — a PHP <code>E_USER_WARNING</code> is emitted and the application continues normally. The XML write that already succeeded is never rolled back.</p><h3 id="automatic-push-via-cron-job" tabindex="-1">Automatic push via cron job <a class="header-anchor" href="#automatic-push-via-cron-job" aria-label="Permalink to &quot;Automatic push via cron job&quot;">​</a></h3><p>When <code>version_control_push</code> is set to <code>&#39;manual&#39;</code>, you control when pushes happen. A cron job is the simplest way to push on a schedule.</p><h4 id="every-n-minutes" tabindex="-1">Every N minutes <a class="header-anchor" href="#every-n-minutes" aria-label="Permalink to &quot;Every N minutes&quot;">​</a></h4><p>Open the crontab editor:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span></code></pre></div><p>Push every 15 minutes (replace paths to match your setup):</p><div class="language-cron vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cron</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*/15 * * * * cd /var/www/my-project/storage &amp;&amp; git push &gt;&gt; /var/log/dom-orm-push.log 2&gt;&amp;1</span></span></code></pre></div><h4 id="mercurial" tabindex="-1">Mercurial <a class="header-anchor" href="#mercurial" aria-label="Permalink to &quot;Mercurial&quot;">​</a></h4><p>Replace <code>git push</code> with <code>hg push</code>:</p><div class="language-cron vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cron</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*/15 * * * * cd /var/www/my-project/storage &amp;&amp; hg push &gt;&gt; /var/log/dom-orm-push.log 2&gt;&amp;1</span></span></code></pre></div><h4 id="quick-cron-reference" tabindex="-1">Quick cron reference <a class="header-anchor" href="#quick-cron-reference" aria-label="Permalink to &quot;Quick cron reference&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>*/15 * * * *</code></td><td>Every 15 minutes</td><td>—</td></tr><tr><td><code>*/30 * * * *</code></td><td>Every 30 minutes</td><td>—</td></tr><tr><td><code>0 */2 * * *</code></td><td>Every 2 hours</td><td>on the hour</td></tr><tr><td><code>0 */6 * * *</code></td><td>Every 6 hours</td><td>on the hour</td></tr><tr><td><code>0 3 * * *</code></td><td>Once a day</td><td>03:00</td></tr></tbody></table><blockquote><p><strong>Security note:</strong> Avoid embedding credentials in cron commands or remote URLs. Use SSH keys or a Git credential helper so secrets are never stored in plain text in the crontab.</p></blockquote>`,25)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
